import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 综合复习与自测 · 第24–35课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第三册：培养技能 · 综合复习与自测 · 第24–35课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-3/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第12–23课","link":"/life/english/new-concept/book-3/review-part-02"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第36–47课","link":"/life/english/new-concept/book-3/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第12–23课","link":"/life/english/new-concept/book-3/review-part-02"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第36–47课","link":"/life/english/new-concept/book-3/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-3/review-part-03.md","filePath":"life/english/new-concept/book-3/review-part-03.md"}'),n={name:"life/english/new-concept/book-3/review-part-03.md"};function r(l,e,i,h,p,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第三册-培养技能-·-综合复习与自测-·-第24–35课" tabindex="-1">第三册：培养技能 · 综合复习与自测 · 第24–35课 <a class="header-anchor" href="#第三册-培养技能-·-综合复习与自测-·-第24–35课" aria-label="Permalink to &quot;第三册：培养技能 · 综合复习与自测 · 第24–35课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-24-·-同位语从句与定语从句" tabindex="-1">Lesson 24 · 同位语从句与定语从句 <a class="header-anchor" href="#lesson-24-·-同位语从句与定语从句" aria-label="Permalink to &quot;Lesson 24 · 同位语从句与定语从句 {#lesson-24-·-同位语从句与定语从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The discovery that the letter was unsigned raised new questions.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>例句 that 后的从句是否缺宾语？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不缺。</p><p><strong>解析：</strong> was unsigned 已形成完整主系表结构。</p></details><p><strong>表达迁移：</strong> 用三句写旧信件引发的疑问，只陈述已知内容和待证实部分。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We found an unsigned letter in a drawer. The fact that it mentioned our old address surprised us. We still do not know who wrote it.</p><p>fact 后从句陈述已知细节，最后一句明确未知内容。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-024">回看本课</a></p><h2 id="lesson-25-·-过去完成进行时" tabindex="-1">Lesson 25 · 过去完成进行时 <a class="header-anchor" href="#lesson-25-·-过去完成进行时" aria-label="Permalink to &quot;Lesson 25 · 过去完成进行时 {#lesson-25-·-过去完成进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The crew had been sailing for six hours when the wind finally changed.</p><h3 id="练习-1-24" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-24" aria-label="Permalink to &quot;练习 1 {#练习-1-24}&quot;">​</a></h3><p>例句强调里程还是持续时间？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 持续时间。</p><p><strong>解析：</strong> for six hours 给出时长。</p></details><p><strong>表达迁移：</strong> 用三句报告虚构航行进展，区分过程和已完成的距离。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We had been rowing for an hour when the fog lifted. By then, we had covered only two kilometres. A strong current had slowed us down.</p><p>持续、数量与原因分别用合适结构，避免只凭时间推算进度。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-025">回看本课</a></p><h2 id="lesson-26-·-too-与-enough-的位置" tabindex="-1">Lesson 26 · too 与 enough 的位置 <a class="header-anchor" href="#lesson-26-·-too-与-enough-的位置" aria-label="Permalink to &quot;Lesson 26 · too 与 enough 的位置 {#lesson-26-·-too-与-enough-的位置}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The tin is wide enough to hold the cards, but it is too shallow for the wooden pieces.</p><h3 id="练习-1-25" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-25" aria-label="Permalink to &quot;练习 1 {#练习-1-25}&quot;">​</a></h3><p>填空：We need ___ room for two boxes.（enough/too）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> enough</p><p><strong>解析：</strong> enough 放名词前表示足够数量。</p></details><p><strong>表达迁移：</strong> 用三句写容器征集说明，明确用途、尺寸条件和状态。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need a box for twenty model parts. It must be deep enough to hold the tallest piece upright. A used box is fine if the lid closes securely.</p><p>需求围绕可检验功能，避免空泛地只说 large。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-026">回看本课</a></p><h2 id="lesson-27-·-不定代词的后置修饰" tabindex="-1">Lesson 27 · 不定代词的后置修饰 <a class="header-anchor" href="#lesson-27-·-不定代词的后置修饰" aria-label="Permalink to &quot;Lesson 27 · 不定代词的后置修饰 {#lesson-27-·-不定代词的后置修饰}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We found nothing expensive in the cabin, but there was everything we needed.</p><h3 id="练习-1-26" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-26" aria-label="Permalink to &quot;练习 1 {#练习-1-26}&quot;">​</a></h3><p>改正：We need useful something.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We need something useful.</p><p><strong>解析：</strong> 形容词置于不定代词后。</p></details><p><strong>表达迁移：</strong> 写三句描述简朴出行准备，包含不需要的东西和必要条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I packed nothing decorative for the trip. Everything in my bag served a clear purpose. I still carried a small first-aid kit and enough water.</p><p>nothing 的否定范围限于装饰物，不把简朴误写为完全不做准备。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-027">回看本课</a></p><h2 id="lesson-28-·-条件句中的礼貌距离" tabindex="-1">Lesson 28 · 条件句中的礼貌距离 <a class="header-anchor" href="#lesson-28-·-条件句中的礼貌距离" aria-label="Permalink to &quot;Lesson 28 · 条件句中的礼貌距离 {#lesson-28-·-条件句中的礼貌距离}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If you included the carrying case, I would consider paying the full price.</p><h3 id="练习-1-27" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-27" aria-label="Permalink to &quot;练习 1 {#练习-1-27}&quot;">​</a></h3><p>例句承诺一定支付全价吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> would consider 只是会考虑。</p></details><p><strong>表达迁移：</strong> 写三句二手物品议价，说明检查结果、条件和可接受方案。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The handle is loose, although the case looks clean. If you repaired it, I would pay the listed price. Otherwise, I could offer ten pounds less.</p><p>让步句承认优点，条件句明确修理要求，otherwise 引出另一方案。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-028">回看本课</a></p><h2 id="lesson-29-·-whether-从句与选择范围" tabindex="-1">Lesson 29 · whether 从句与选择范围 <a class="header-anchor" href="#lesson-29-·-whether-从句与选择范围" aria-label="Permalink to &quot;Lesson 29 · whether 从句与选择范围 {#lesson-29-·-whether-从句与选择范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Whether the joke works depends partly on what the audience already knows.</p><h3 id="练习-1-28" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-28" aria-label="Permalink to &quot;练习 1 {#练习-1-28}&quot;">​</a></h3><p>例句中的整句谓语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> depends</p><p><strong>解析：</strong> whether 从句整体是主语。</p></details><p><strong>表达迁移：</strong> 写三句评价一次玩笑失败的原因，提出更合适的表达。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The joke relied on an unfamiliar local saying. Several guests looked confused rather than amused. A short explanation would have helped them understand the reference.</p><p>把原因定位于共享背景不足，避免直接评价听者的能力。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-029">回看本课</a></p><h2 id="lesson-30-·-情态动词加完成式推断" tabindex="-1">Lesson 30 · 情态动词加完成式推断 <a class="header-anchor" href="#lesson-30-·-情态动词加完成式推断" aria-label="Permalink to &quot;Lesson 30 · 情态动词加完成式推断 {#lesson-30-·-情态动词加完成式推断}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Someone must have opened the cupboard, because the flour had been moved.</p><h3 id="练习-1-29" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-29" aria-label="Permalink to &quot;练习 1 {#练习-1-29}&quot;">​</a></h3><p>例句是否声称说话者亲眼看见开柜子？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> because 引出间接证据。</p></details><p><strong>表达迁移：</strong> 为夜间怪声写三句解释，包含线索、可能性和下一步检查。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The noise began when the wind rose. A loose shutter may have struck the wall. We will examine the hinges in daylight.</p><p>先报告同时发生的现象，再提出可检验假设，避免把相关性直接当作证明。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-030">回看本课</a></p><h2 id="lesson-31-·-非限定性定语从句" tabindex="-1">Lesson 31 · 非限定性定语从句 <a class="header-anchor" href="#lesson-31-·-非限定性定语从句" aria-label="Permalink to &quot;Lesson 31 · 非限定性定语从句 {#lesson-31-·-非限定性定语从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Mr Vale, who repairs clocks for fun, keeps a tiny workshop in his kitchen.</p><h3 id="练习-1-30" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-30" aria-label="Permalink to &quot;练习 1 {#练习-1-30}&quot;">​</a></h3><p>删去例句中的插入从句，主句是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Mr Vale keeps a tiny workshop in his kitchen.</p><p><strong>解析：</strong> 非限定从句不影响主句完整性。</p></details><p><strong>表达迁移：</strong> 写三句描绘一位有特别爱好的邻居，至少一处用非限定从句。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mrs Lane, who collects broken umbrellas, makes colourful shopping bags. She hangs each new bag on the garden fence. Visitors often stop to ask how it was made.</p><p>具体动作呈现性格，补充从句交代材料来源，人物形象自然形成。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-031">回看本课</a></p><h2 id="lesson-32-·-现在完成时被动" tabindex="-1">Lesson 32 · 现在完成时被动 <a class="header-anchor" href="#lesson-32-·-现在完成时被动" aria-label="Permalink to &quot;Lesson 32 · 现在完成时被动 {#lesson-32-·-现在完成时被动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Three wooden beams have been recovered, but the vessel has not yet been identified.</p><h3 id="练习-1-31" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-31" aria-label="Permalink to &quot;练习 1 {#练习-1-31}&quot;">​</a></h3><p>填空：The location ___ been confirmed.（has/have）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> location 为单数。</p></details><p><strong>表达迁移：</strong> 写三句虚构水下调查进度，包含已完成、未完成和计划。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The outline of the vessel has been mapped. No personal objects have been recovered yet. The team will inspect the deeper section next week.</p><p>完成时被动汇报当前进度，yet 限定尚无结果，未来句交代下一步。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-032">回看本课</a></p><h2 id="lesson-33-·-否定副词前置倒装" tabindex="-1">Lesson 33 · 否定副词前置倒装 <a class="header-anchor" href="#lesson-33-·-否定副词前置倒装" aria-label="Permalink to &quot;Lesson 33 · 否定副词前置倒装 {#lesson-33-·-否定副词前置倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Never had I seen the station so quiet before that morning.</p><h3 id="练习-1-32" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-32" aria-label="Permalink to &quot;练习 1 {#练习-1-32}&quot;">​</a></h3><p>改写：I rarely travel without a notebook.（Rarely 开头）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Rarely do I travel without a notebook.</p><p><strong>解析：</strong> 补入 do 并把主语置于其后。</p></details><p><strong>表达迁移：</strong> 写三句难忘经历，包含一个倒装句和具体细节。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rarely have I travelled through such dense fog. The bus stopped beside a closed bakery for nearly an hour. When sunlight finally reached the windows, everyone cheered.</p><p>倒装给整体感受，后两句提供可见情节支持感受。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">回看本课</a></p><h2 id="lesson-34-·-分词状语的逻辑主语" tabindex="-1">Lesson 34 · 分词状语的逻辑主语 <a class="header-anchor" href="#lesson-34-·-分词状语的逻辑主语" aria-label="Permalink to &quot;Lesson 34 · 分词状语的逻辑主语 {#lesson-34-·-分词状语的逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Looking beneath the frame, Maya noticed a small handwritten label.</p><h3 id="练习-1-33" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-33" aria-label="Permalink to &quot;练习 1 {#练习-1-33}&quot;">​</a></h3><p>例句是谁查看画框下方？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Maya</p><p><strong>解析：</strong> 分词逻辑主语应与主句主语一致。</p></details><p><strong>表达迁移：</strong> 用三句描述发现旧物，包含一个主语一致的分词短语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Sorting the books, I found a sketch between two pages. A date in the corner caught my eye. I photographed the sketch before asking the owner about its history.</p><p>分词主语清楚，发现后先记录再询问，未把猜测写成价值鉴定。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">回看本课</a></p><h2 id="lesson-35-·-情态动词的被动结构" tabindex="-1">Lesson 35 · 情态动词的被动结构 <a class="header-anchor" href="#lesson-35-·-情态动词的被动结构" aria-label="Permalink to &quot;Lesson 35 · 情态动词的被动结构 {#lesson-35-·-情态动词的被动结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Both statements should be examined before a decision is announced.</p><h3 id="练习-1-34" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-34" aria-label="Permalink to &quot;练习 1 {#练习-1-34}&quot;">​</a></h3><p>例句能证明双方陈述已经审查吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> should 表示应当采取的措施。</p></details><p><strong>表达迁移：</strong> 写三句虚构社区争议处理流程，包含一项原则和两项具体步骤。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Every complaint should be heard without interruption. The chair recorded each resident&#39;s main concern. A written explanation was sent after the meeting.</p><p>第一句说明原则，后二句报告实际动作，建议与事实清楚分开。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">回看本课</a></p>',100)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
